mapper.select:
SELECT M1.idx AS "idx", M1.sys_id AS "sysId", M1.user_id AS "userId", M1.user_nm AS "userNm", M1.athrty_cd AS "athrtyCd", M1.join_ymd AS "joinYmd", M1.user_stat_cd AS "userStatCd", M1.rgst_bgng_dt AS "rgstBgngDt", M1.rgst_end_dt AS "rgstEndDt", IFNULL(A.athrty_level, 99) AS "athrtyLevel", M2.email AS "email", M2.mbl_telno AS "mblTelno", M2.zip_cd AS "zipCd", M2.base_addr AS "baseAddr", M2.dtl_addr AS "dtlAddr", M2.img_file_sn AS "imgFileSn", M2.rmrk AS "rmrk", M2.emp_no AS "empNo", M2.dept_cd AS "deptCd", M2.position_cd AS "positionCd", M2.emp_stat_cd AS "empStatCd", M2.hire_dt AS "hireDt", M2.resign_dt AS "resignDt" FROM TN_MEM_M001 M1 LEFT OUTER JOIN TN_ATH_A001 A ON M1.sys_id = A.sys_id AND M1.athrty_cd = A.athrty_com_cd LEFT OUTER JOIN TN_MEM_M002 M2 ON M1.idx = M2.user_idx WHERE M1.sys_id = #{sysId}
AND M1.athrty_cd != 'SUPR'
AND IFNULL(A.athrty_level, 99) >= #{currentAthrtyLevel}
AND M1.athrty_cd = #{athrtyCd}
AND M1.user_id LIKE CONCAT('%', #{searchUserId}, '%')
AND M1.user_nm LIKE CONCAT('%', #{searchUserNm}, '%')
AND M1.user_stat_cd = #{searchUserStatCd}
ORDER BY M1.idx DESC

mapper.update:
UPDATE TN_MEM_M001 SET user_nm = #{userNm}, athrty_cd = #{athrtyCd}, user_stat_cd = #{userStatCd}, rgst_bgng_dt = CASE WHEN #{rgstBgngDt} = '' THEN NULL ELSE #{rgstBgngDt} END, rgst_end_dt = CASE WHEN #{rgstEndDt} = '' THEN NULL ELSE #{rgstEndDt} END,
pswd = #{pswd},
last_mdfr_id = #{registerId}, last_mdfcn_dt = NOW() WHERE sys_id = #{sysId} AND user_id = #{userId}
